def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    m = len(ranks)
    bit = [0] * (m + 1)
    result = [0] * len(a)

    for i, value in enumerate(a):
        rank = ranks[value]

        # Count previous window values less than or equal to value.
        count = 0
        j = rank
        while j > 0:
            count += bit[j]
            j -= j & -j

        result[i] = min(i, k) - count

        j = rank
        while j <= m:
            bit[j] += 1
            j += j & -j

        # Prepare the window for the next position.
        if i >= k:
            j = ranks[a[i - k]]
            while j <= m:
                bit[j] -= 1
                j += j & -j

    return result
